1) lib/demo-role.ts:
```
import { cookies } from 'next/headers';
export type ViewerRole = 'host' | 'participant';
export const DEMO_ROLE_COOKIE = 'gather-demo-role';
export async function getDemoViewerRole(): Promise<ViewerRole> {
  const store = await cookies();
  return store.get(DEMO_ROLE_COOKIE)?.value === 'participant' ? 'participant' : 'host';
}
```
2) lib/demo-role-actions.ts:
```
'use server';
import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';
import { DEMO_ROLE_COOKIE, type ViewerRole } from '@/lib/demo-role';
export async function setDemoViewerRole(role: ViewerRole) {
  const store = await cookies();
  store.set(DEMO_ROLE_COOKIE, role, { path: '/' });
  redirect('/events');
}
```
